/// <summary>
/// MPJ_2573_VendorRemittanceAdviceFormatChanges
/// Processes payment lines for report.
/// </summary>
public class METBankPaymAdvicePaymentLineGenerator
{
}

Method.Source:
    internal List getPaymentLines(METBankPaymAdviceContract _bankPaymAdviceContract)
    {
        List paymentList = new List(Types::Record);

        Query query = new Query(QueryStr(BankPaymAdvicePaymentLineQuery));
        this.applyRangesToQuery(query, _bankPaymAdviceContract);

        // Bug 71205: MET Payment advice report printed for each individual payment journal line
        // Need to group by vendor account and payment reference
        this.applyGroupByToQuery(query);

        QueryRun queryRun = new QueryRun(query);
        queryRun.setRecord(this.generatePaymentLineAccountNames(_bankPaymAdviceContract.parmLedgerJournalId()));

        LedgerJournalTrans ledgerJournalTrans;

        while (queryRun.next())
        {
            ledgerJournalTrans = queryRun.get(tableNum(LedgerJournalTrans));

            if (ledgerJournalTrans)
            {
                LedgerJournalTrans ledgerJournalTransCopy;
                ledgerJournalTransCopy.data(ledgerJournalTrans);

                paymentList.addEnd(ledgerJournalTransCopy);
            }
        }

        return paymentList;
    }

    /// <summary>
    /// Bug 71205: MET Payment advice report printed for each individual payment journal line
    /// The payment advise report needs to be grouped by vendor and payment reference
    /// </summary>
    /// <param name = "_query"></param>
    private void applyGroupByToQuery(Query _query)
    {
        // group by payment reference and journal num so we can reselect a payment line later
        QueryBuildDataSource qbds = _query.dataSourceTable(tableNum(LedgerJournalTrans));
        qbds.addGroupByField(fieldNum(LedgerJournalTrans, JournalNum));
        qbds.addGroupByField(fieldNum(LedgerJournalTrans, PaymReference));

        // remove the order by from query as it's not part of the group by
        qbds = _query.dataSourceTable(tableNum(DimensionCombinationValueNameTmp));
        qbds.removeOrderByField(fieldNum(DimensionCombinationValueNameTmp, Name));
    }

    private void applyRangesToQuery(Query _query, METBankPaymAdviceContract _bankPaymAdviceContract)
    {
        QueryBuildDataSource qbds = _query.dataSourceTable(tableNum(LedgerJournalTrans));

        SysQuery::findOrCreateRange(qbds, fieldNum(LedgerJournalTrans, JournalNum)).value(queryValue(_bankPaymAdviceContract.parmLedgerJournalId()));

        if (_bankPaymAdviceContract.parmAccountNum() != '')
        {
            SysQuery::addDimensionAttributeRange(_query, qbds.name(), fieldStr(LedgerJournalTrans, LedgerDimension), DimensionComponent::LedgerDimensionDisplayValue, _bankPaymAdviceContract.parmAccountNum());
        }

        if (_bankPaymAdviceContract.parmPaymMode() != '')
        {
            SysQuery::findOrCreateRange(qbds, fieldNum(LedgerJournalTrans, PaymMode)).value(queryValue(_bankPaymAdviceContract.parmPaymMode()));
        }

        if (_bankPaymAdviceContract.parmCompanyBankAccountId())
        {
            SysQuery::addDimensionAttributeRange(_query, qbds.name(), fieldStr(LedgerJournalTrans, OffsetLedgerDimension), DimensionComponent::LedgerDimensionDisplayValue, _bankPaymAdviceContract.parmCompanyBankAccountId());
        }

        // Bug 71205: Print Remittance Advice - Cannot print D365 remittance advice to Screen
        // Need to update query payment status from Sent to Approved        
        SysQuery::findOrCreateRange(qbds, fieldNum(LedgerJournalTrans, PaymentStatus)).value(queryValue(_bankPaymAdviceContract.parmPaymentStatus()));

    }

internal static METBankPaymAdvicePaymentLineGenerator construct()
{
    return new METBankPaymAdvicePaymentLineGenerator();
}
